const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Gemini CLI";
pres.title = "Global CO2 Emissions";

const theme = {
  primary: "1A2530",   // Dark slate
  secondary: "3F5161", // Muted slate
  accent: "D3462C",    // Rust Red
  light: "F4F6F8",     // Off-white/light gray
  bg: "FFFFFF"         // White
};

// --- Helper: Add Badge ---
function addBadge(slide, number) {
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fill: { color: theme.secondary },
    rectRadius: 0.15
  });
  slide.addText(number.toString().padStart(2, '0'), {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });
}

// ==========================================
// Slide 1: Title Slide (Cover)
// ==========================================
function createSlide1() {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  slide.addText("Global CO₂ Emissions", {
    x: 1, y: 1.5, w: 8, h: 1,
    fontSize: 48, fontFace: "Arial",
    color: theme.bg, bold: true, align: "left"
  });

  slide.addText("Trends, Regional Shifts, and Per Capita Inequalities", {
    x: 1, y: 2.5, w: 8, h: 0.8,
    fontSize: 28, fontFace: "Arial",
    color: theme.light, align: "left"
  });

  slide.addShape(pres.shapes.LINE, {
    x: 1, y: 3.5, w: 1.5, h: 0,
    line: { color: theme.accent, width: 4 }
  });

  slide.addText("1750–2024 Overview\nData: Global Carbon Budget 2025, NASA", {
    x: 1, y: 4.0, w: 8, h: 0.8,
    fontSize: 16, fontFace: "Arial",
    color: "A0B0C0", align: "left"
  });
}

// ==========================================
// Slide 2: Atmospheric CO2 Milestone
// ==========================================
function createSlide2() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText("Atmospheric CO₂ Reaches 429 ppm", {
    x: 0.5, y: 0.3, w: 9, h: 0.8,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addText("50% Above Pre-Industrial Levels", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 20, fontFace: "Arial",
    color: theme.secondary
  });

  // Big Callout
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 1.8, w: 4, h: 2.5,
    fill: { color: theme.light },
    rectRadius: 0.1
  });
  slide.addText("429", {
    x: 0.5, y: 2.1, w: 4, h: 1.2,
    fontSize: 72, fontFace: "Arial",
    color: theme.accent, bold: true, align: "center"
  });
  slide.addText("Parts per million (ppm)\nFeb 2026 Measurement (NOAA)", {
    x: 0.5, y: 3.2, w: 4, h: 0.8,
    fontSize: 14, fontFace: "Arial",
    color: theme.secondary, align: "center"
  });

  // Timeline / Context
  slide.addText("Context", {
    x: 5.0, y: 1.8, w: 4.5, h: 0.4,
    fontSize: 18, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addText(
    "• Pre-industrial baseline: ~280 ppm\n\n" +
    "• At least 1.5x greater than natural increase after last ice age\n\n" +
    "• Sharp acceleration observed since mid-20th century\n\n" +
    "• Driven primarily by coal, oil, and natural gas", {
    x: 5.0, y: 2.4, w: 4.5, h: 2.0,
    fontSize: 16, fontFace: "Arial",
    color: theme.secondary,
    bullet: true
  });

  addBadge(slide, 2);
}

// ==========================================
// Slide 3: Global Emissions Six-Fold
// ==========================================
function createSlide3() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText("Global Fossil Fuel CO₂ Emissions Grew Six-Fold", {
    x: 0.5, y: 0.3, w: 9, h: 0.8,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addText("From 6 Billion tonnes in 1950 to 35+ Billion Tonnes Today", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 20, fontFace: "Arial",
    color: theme.secondary
  });

  // Line chart using PptxGenJS charts
  const dataChart = [
    {
      name: "Global Emissions (Billion tonnes)",
      labels: ["1750", "1900", "1950", "1990", "2024"],
      values: [0, 2, 6, 20, 35]
    }
  ];

  slide.addChart(pres.charts.LINE, dataChart, {
    x: 0.5, y: 1.6, w: 8.5, h: 3.2,
    chartColors: [theme.accent],
    lineDataSymbol: "circle",
    lineSize: 3,
    showLegend: true, legendPos: 'b',
    valAxisMinVal: 0,
    valAxisMaxVal: 40,
    valGridLine: { color: theme.light, size: 1 },
    dataLabelColor: theme.secondary,
    showValue: true,
    dataLabelFontSize: 12
  });

  addBadge(slide, 3);
}

// ==========================================
// Slide 4: China Surpasses US
// ==========================================
function createSlide4() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText("China Now Emits Over 12 Billion Tonnes", {
    x: 0.5, y: 0.3, w: 9, h: 0.8,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addText("More Than Double the United States", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 20, fontFace: "Arial",
    color: theme.secondary
  });

  // We can include figure_3.jpg if it exists, otherwise a table
  slide.addImage({
    path: "/app/benchmark/assets/figure_3.jpg",
    x: 0.5, y: 1.8, w: 5, h: 3.2,
    sizing: { type: "contain" }
  });

  const tableData = [
    [
      { text: "Country / Region", options: { bold: true, fill: theme.primary, color: theme.bg } },
      { text: "Annual CO₂ (Bt)", options: { bold: true, fill: theme.primary, color: theme.bg } },
      { text: "Trend", options: { bold: true, fill: theme.primary, color: theme.bg } }
    ],
    ["China", "~12.5 (~27%)", "Slight increase"],
    ["United States", "~5.0 (~14%)", "Declining"],
    ["India", "~3.0 (~8%)", "Rising"],
    ["EU-27", "~2.7 (~7%)", "Declining"],
    ["Germany", "~0.6 (~1.7%)", "Declining"],
    ["Brazil", "~0.5 (~1.4%)", "Stable"]
  ];

  slide.addTable(tableData, {
    x: 5.8, y: 1.8, w: 3.8, h: 3.0,
    border: { type: "solid", color: theme.light, pt: 1 },
    colW: [1.5, 1.2, 1.1],
    fontSize: 12,
    fontFace: "Arial",
    rowH: 0.4,
    valign: "middle"
  });

  addBadge(slide, 4);
}

// ==========================================
// Slide 5: Regional Share Shift
// ==========================================
function createSlide5() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText("Asia Now Accounts for ~50% of Global Emissions", {
    x: 0.5, y: 0.3, w: 9, h: 0.8,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addText("US + Europe combined have fallen below one-third of the global total", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 20, fontFace: "Arial",
    color: theme.secondary
  });

  const chartData = [
    {
      name: "Europe + US",
      labels: ["1900", "1950", "2024"],
      values: [90, 85, 30]
    },
    {
      name: "Asia",
      labels: ["1900", "1950", "2024"],
      values: [5, 8, 50]
    },
    {
      name: "Rest of World (inc. Africa/SA)",
      labels: ["1900", "1950", "2024"],
      values: [5, 7, 20]
    }
  ];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 1.6, w: 6.0, h: 3.5,
    barDir: "col",
    barGrouping: "stacked",
    chartColors: [theme.secondary, theme.accent, "A0B0C0"],
    showLegend: true, legendPos: 'b',
    valAxisMaxVal: 100,
    valGridLine: { color: theme.light, size: 1 },
    dataLabelColor: "FFFFFF",
    showValue: true,
    dataLabelFontSize: 12
  });

  slide.addText(
    "Africa and South America each contribute only 3–4% today, comparable to international aviation and shipping combined.", {
    x: 6.8, y: 2.2, w: 2.7, h: 2.0,
    fontSize: 16, fontFace: "Arial",
    color: theme.primary,
    bold: true
  });

  addBadge(slide, 5);
}

// ==========================================
// Slide 6: Per Capita Gap
// ==========================================
function createSlide6() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText("Per Capita Gap: A 150× Disparity", {
    x: 0.5, y: 0.3, w: 9, h: 0.8,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addText("15 tonnes in the US vs. 0.1 tonnes in Chad", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 20, fontFace: "Arial",
    color: theme.secondary
  });

  // PptxGenJS Horizontal Bar Chart
  const chartData = [
    {
      name: "Per Capita CO2 (tonnes/year)",
      labels: ["US", "Canada", "China", "EU-27", "World", "UK", "India", "Chad/Kenya"],
      values: [15, 13, 9, 7, 5, 4, 2, 0.1]
    }
  ];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 1.5, w: 8.5, h: 3.5,
    barDir: "bar",
    chartColors: [theme.accent],
    showLegend: false,
    valAxisMaxVal: 16,
    valGridLine: { color: theme.light, size: 1 },
    showValue: true,
    dataLabelFontSize: 14,
    dataLabelColor: theme.primary
  });

  addBadge(slide, 6);
}

// ==========================================
// Slide 7: 2024 Annual Change Map
// ==========================================
function createSlide7() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText("2024 Snapshot: Annual Change in Emissions", {
    x: 0.5, y: 0.3, w: 9, h: 0.8,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addText("US and Europe Cut Emissions While Russia and SE Asia Increase", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 20, fontFace: "Arial",
    color: theme.secondary
  });

  // Image for figure_4.jpg
  slide.addImage({
    path: "/app/benchmark/assets/figure_4.jpg",
    x: 0.5, y: 1.5, w: 6.0, h: 3.5,
    sizing: { type: "contain" }
  });

  slide.addText(
    "Declines (Blue):\n" +
    "• US and much of Europe: -1% to -5%\n\n" +
    "Increases (Orange/Red):\n" +
    "• Russia, parts of Africa, and SE Asia: +2% to +10%\n" +
    "• Select South American nations: >10%", {
    x: 6.8, y: 1.8, w: 2.8, h: 2.5,
    fontSize: 16, fontFace: "Arial",
    color: theme.primary,
    bullet: true
  });

  addBadge(slide, 7);
}

// ==========================================
// Slide 8: Energy Mix
// ==========================================
function createSlide8() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText("Energy Mix Drives Per Capita Differences", {
    x: 0.5, y: 0.3, w: 9, h: 0.8,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addText("Similar Living Standards, Very Different Emissions Profiles", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 20, fontFace: "Arial",
    color: theme.secondary
  });

  // Table
  const tableData = [
    [
      { text: "Country", options: { bold: true, fill: theme.primary, color: theme.bg } },
      { text: "Per Capita CO₂", options: { bold: true, fill: theme.primary, color: theme.bg } },
      { text: "Primary Energy Profile", options: { bold: true, fill: theme.primary, color: theme.bg } }
    ],
    ["France", "~4 tonnes", "High nuclear and renewables share"],
    ["United Kingdom", "~4 tonnes", "High renewables, phasing out coal"],
    ["Germany", "~6-7 tonnes", "Higher fossil fuel / coal share"],
    ["Netherlands", "~7 tonnes", "Higher fossil fuel / natural gas reliance"]
  ];

  slide.addTable(tableData, {
    x: 0.5, y: 1.8, w: 8.5, h: 1.8,
    border: { type: "solid", color: theme.light, pt: 1 },
    colW: [2.0, 2.0, 4.5],
    fontSize: 16,
    fontFace: "Arial",
    rowH: 0.5,
    valign: "middle"
  });

  slide.addText(
    "Policy Insight:\nProsperity does not dictate a fixed level of emissions. " +
    "A structural shift to nuclear and renewable energy can decouple high living standards from carbon intensity.", {
    x: 0.5, y: 4.0, w: 8.5, h: 1.0,
    fontSize: 16, fontFace: "Arial",
    color: theme.secondary,
    italic: true
  });

  addBadge(slide, 8);
}

// ==========================================
// Slide 9: Key Takeaways
// ==========================================
function createSlide9() {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  slide.addText("Key Takeaways", {
    x: 0.5, y: 0.5, w: 9, h: 0.8,
    fontSize: 36, fontFace: "Arial",
    color: theme.bg, bold: true
  });
  slide.addText("Emissions Are Still Rising, But the Map of Responsibility Is Shifting", {
    x: 0.5, y: 1.2, w: 9, h: 0.4,
    fontSize: 22, fontFace: "Arial",
    color: theme.accent
  });

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 1.8, w: 9, h: 3.2,
    fill: { color: theme.secondary },
    rectRadius: 0.05
  });

  slide.addText(
    "• Global emissions exceed 35 Bt and have not yet peaked, continuing an upward trajectory.\n\n" +
    "• China alone emits >25% of the global total, double that of the US, while India is rising rapidly.\n\n" +
    "• Per capita inequalities remain extreme, with a 150× disparity separating the highest emitters (US/Australia) from the lowest (Chad/Niger).\n\n" +
    "• US and Europe are declining in annual emissions, but retain massive historical cumulative responsibility.\n\n" +
    "• Policy and energy mix choices — not just prosperity — determine per capita outcomes, as seen in France vs. Germany.", {
    x: 0.7, y: 2.0, w: 8.6, h: 2.8,
    fontSize: 18, fontFace: "Arial",
    color: theme.bg,
    bullet: { type: 'bullet' },
    lineSpacing: 24
  });

  addBadge(slide, 9);
}

// Generate all
createSlide1();
createSlide2();
createSlide3();
createSlide4();
createSlide5();
createSlide6();
createSlide7();
createSlide8();
createSlide9();

pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => {
    console.log("Presentation created successfully: /app/output/final_deck.pptx");
  })
  .catch((err) => {
    console.error("Error creating presentation:", err);
  });

const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Gemini CLI";
pres.title = "Global CO2 Emissions";

const theme = {
  primary: "1A2530",   // Dark slate
  secondary: "3F5161", // Muted slate
  accent: "D3462C",    // Rust Red
  light: "F4F6F8",     // Off-white/light gray
  bg: "FFFFFF"         // White
};

// --- Helper: Add Badge ---
function addBadge(slide, number) {
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fill: { color: theme.secondary },
    rectRadius: 0.15
  });
  slide.addText(number.toString().padStart(2, '0'), {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });
}

// ==========================================
// Slide 1: Title Slide (Cover)
// ==========================================
function createSlide1() {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  slide.addText("Global CO₂ Emissions", {
    x: 1, y: 1.5, w: 8, h: 1,
    fontSize: 48, fontFace: "Arial",
    color: theme.bg, bold: true, align: "left"
  });

  slide.addText("Trends, Regional Shifts, and Per Capita Inequalities", {
    x: 1, y: 2.5, w: 8, h: 0.8,
    fontSize: 28, fontFace: "Arial",
    color: theme.light, align: "left"
  });

  slide.addShape(pres.shapes.LINE, {
    x: 1, y: 3.5, w: 1.5, h: 0,
    line: { color: theme.accent, width: 4 }
  });

  slide.addText("1750–2024 Overview\nData: Global Carbon Budget 2025, NASA", {
    x: 1, y: 4.0, w: 8, h: 0.8,
    fontSize: 16, fontFace: "Arial",
    color: "A0B0C0", align: "left"
  });
}

// ==========================================
// Slide 2: Atmospheric CO2 Milestone
// ==========================================
function createSlide2() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText("Atmospheric CO₂ Reaches 429 ppm", {
    x: 0.5, y: 0.3, w: 9, h: 0.8,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addText("50% Above Pre-Industrial Levels", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 20, fontFace: "Arial",
    color: theme.secondary
  });

  // Big Callout
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 1.8, w: 4, h: 2.5,
    fill: { color: theme.light },
    rectRadius: 0.1
  });
  slide.addText("429", {
    x: 0.5, y: 2.1, w: 4, h: 1.2,
    fontSize: 72, fontFace: "Arial",
    color: theme.accent, bold: true, align: "center"
  });
  slide.addText("Parts per million (ppm)\nFeb 2026 Measurement (NOAA)", {
    x: 0.5, y: 3.2, w: 4, h: 0.8,
    fontSize: 14, fontFace: "Arial",
    color: theme.secondary, align: "center"
  });

  // Timeline / Context
  slide.addText("Context", {
    x: 5.0, y: 1.8, w: 4.5, h: 0.4,
    fontSize: 18, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addText(
    "• Pre-industrial baseline: ~280 ppm\n\n" +
    "• At least 1.5x greater than natural increase after last ice age\n\n" +
    "• Sharp acceleration observed since mid-20th century\n\n" +
    "• Driven primarily by coal, oil, and natural gas", {
